     9	
    10	/** A lista de mensagens enviadas: aplica as regras de e-mail e registra o resultado. */
    11	public class Outbox {
    12	    private final Database database;
    13	    private final MessageRepository messages;
    14	    private final MailPipeline pipeline;
    15	
    16	    public Outbox(Database database, MessageRepository messages, MailPipeline pipeline) {
    17	        this.database = database;
    18	        this.messages = messages;
    19	        this.pipeline = pipeline;
    20	    }
    21	
    22	    public void send(Message message) {
    23	        List<Message> outgoing = pipeline.process(message);
    24	        database.inTransaction(c -> {
    25	            try (Statement s = c.createStatement()) {
    26	                // mantém a mensagem e a sua cópia lado a lado na lista, mesmo com envios simultâneos
    27	                s.execute("SELECT pg_advisory_xact_lock(727002)");
    28	            }
    29	            for (Message m : outgoing) {
    30	                messages.insert(c, m);
    31	            }
    32	            return null;
    33	        });
    34	    }
    35	
    36	    public List<Message> list() {
    37	        return database.inTransaction(messages::findAll);
    38	    }
    39	}
