     8	import br.com.marealta.pousada.store.RoomRepository;
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.util.List;
    13	import java.util.Map;
    14	import java.util.function.Function;
    15	import java.util.stream.Collectors;
    16	
    17	public class ReportService {
    18	    private final Database database;
    19	    private final RoomRepository rooms;
    20	    private final ReservationRepository reservations;
    21	
    22	    public ReportService(Database database, RoomRepository rooms, ReservationRepository reservations) {
    23	        this.database = database;
    24	        this.rooms = rooms;
    25	        this.reservations = reservations;
    26	    }
    27	
    28	    public String occupancy(LocalDate night) {
    29	        return database.inTransaction(c -> {
    30	            Map<Integer, Room> byNumber = rooms.findAll(c).stream()
    31	                    .collect(Collectors.toMap(Room::number, Function.identity()));
    32	            List<Reservation> occupying = reservations.findPaidOccupying(c, night);
    33	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    34	            for (Reservation r : occupying) {
    35	                csv.append(r.roomNumber()).append(',').append(byNumber.get(r.roomNumber()).type()).append(',')
    36	                        .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    37	            }
    38	            long occupiedRooms = occupying.stream().map(Reservation::roomNumber).distinct().count();
    39	            csv.append("total,").append(occupiedRooms).append('/').append(byNumber.size()).append('\n');
    40	            return csv.toString();
    41	        });
    42	    }
    43	
    44	    public String revenue(YearMonth month) {
    45	        return database.inTransaction(c -> {
    46	            List<Reservation> starting = reservations.findStartingBetween(c, month.atDay(1), month.atEndOfMonth());
    47	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    48	            BigDecimal total = Money.ZERO;
    49	            for (Reservation r : starting) {
    50	                BigDecimal amount = r.retained();
    51	                if (amount.signum() <= 0) {
    52	                    continue;
    53	                }
    54	                csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
    55	                        .append(r.checkOut()).append(',').append(r.status()).append(',').append(amount).append('\n');
    56	                total = Money.round(total.add(amount));
    57	            }
    58	            csv.append("total,").append(total).append('\n');
    59	            return csv.toString();
    60	        });
    61	    }
    62	}
