    10	import br.com.marealta.pousada.domain.Money;
    11	import br.com.marealta.pousada.domain.Status;
    12	import br.com.marealta.pousada.store.Database;
    13	import br.com.marealta.pousada.store.ReservationRepository;
    14	import br.com.marealta.pousada.store.RoomRepository;
    15	import java.sql.SQLException;
    16	import java.util.List;
    17	import java.util.function.UnaryOperator;
    18	
    19	public class ReservationService {
    20	    private final Database database;
    21	    private final RoomRepository rooms;
    22	    private final ReservationRepository reservations;
    23	    private final Outbox outbox;
    24	
    25	    public ReservationService(Database database, RoomRepository rooms, ReservationRepository reservations,
    26	                              Outbox outbox) {
    27	        this.database = database;
    28	        this.rooms = rooms;
    29	        this.reservations = reservations;
    30	        this.outbox = outbox;
    31	    }
    32	
    33	    public List<Room> listRooms() {
    34	        return database.inTransaction(rooms::findAll);
    35	    }
    36	
    37	    public Reservation create(NewReservation request) {
    38	        return database.inTransaction(c -> {
    39	            Room room = rooms.findForUpdate(c, request.roomNumber()).orElseThrow(() ->
    40	                    new ApiException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + request.roomNumber() + " não existe"));
    41	            if (request.guests() > room.capacity()) {
    42	                throw new ApiException(ErrorCode.CAPACITY_EXCEEDED,
    43	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " pessoas");
    44	            }
    45	            if (reservations.existsOverlapping(c, room.number(), request.checkIn(), request.checkOut())) {
    46	                throw new ApiException(ErrorCode.ROOM_UNAVAILABLE,
    47	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    48	            }
    49	            Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    50	            Reservation draft = new Reservation(0, room.number(), request.guestName(), request.guestEmail(),
    51	                    request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan(),
    52	                    quote.nights(), quote.subtotal(), quote.discount(), quote.total(), Status.PENDING,
    53	                    Money.ZERO, null);
    54	            return reservations.insert(c, draft);
    55	        });
    56	    }
    57	
    58	    public Reservation get(long id) {
    59	        return database.inTransaction(c -> load(c, id));
    60	    }
    61	
    62	    public Reservation confirm(long id) {
    63	        Reservation confirmed = transition(id, Reservation::confirm);
    64	        outbox.send(ConfirmationEmail.compose(confirmed, receiptOf(confirmed)));
    65	        return confirmed;
    66	    }
    67	
    68	    public Reservation cancel(long id) {
    69	        return transition(id, Reservation::cancel);
    70	    }
    71	
    72	    public Reservation checkIn(long id) {
    73	        return transition(id, Reservation::startStay);
    74	    }
    75	
    76	    public Receipt checkOut(long id) {
    77	        return receiptOf(transition(id, Reservation::endStay));
    78	    }
    79	
    80	    /** Segunda via do comprovante: só existe para reserva paga. */
    81	    public Receipt document(long id) {
    82	        Reservation reservation = get(id);
    83	        if (!reservation.status().paid()) {
    84	            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,
    85	                    "A reserva " + id + " está " + reservation.status() + " e não tem comprovante");
    86	        }
    87	        return receiptOf(reservation);
    88	    }
    89	
    90	    private Reservation transition(long id, UnaryOperator<Reservation> change) {
    91	        return database.inTransaction(c -> {
    92	            Reservation changed = change.apply(reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id)));
    93	            reservations.update(c, changed);
    94	            return changed;
    95	        });
    96	    }
    97	
    98	    private Receipt receiptOf(Reservation reservation) {
    99	        return database.inTransaction(c -> {
   100	            Room room = rooms.find(c, reservation.roomNumber()).orElseThrow();
   101	            return Receipt.of(reservation, room);
   102	        });
   103	    }
   104	
   105	    private Reservation load(java.sql.Connection c, long id) throws SQLException {
   106	        return reservations.find(c, id).orElseThrow(() -> notFound(id));
   107	    }
   108	
   109	    private ApiException notFound(long id) {
   110	        return new ApiException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
   111	    }
   112	}
