     1	package br.com.marealta.pousada.web;
     2	
     3	import br.com.marealta.pousada.domain.ApiException;
     4	import br.com.marealta.pousada.domain.ErrorCode;
     5	import br.com.marealta.pousada.domain.RatePlan;
     6	import br.com.marealta.pousada.service.NewReservation;
     7	import com.fasterxml.jackson.core.JsonProcessingException;
     8	import com.fasterxml.jackson.databind.JsonNode;
     9	import com.fasterxml.jackson.databind.ObjectMapper;
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Lê e valida o corpo do POST /reservations. */
    14	final class ReservationRequest {
    15	    private ReservationRequest() {
    16	    }
    17	
    18	    static NewReservation parse(ObjectMapper mapper, String body) {
    19	        JsonNode json;
    20	        try {
    21	            json = mapper.readTree(body);
    22	        } catch (JsonProcessingException e) {
    23	            throw invalid("O corpo não é um JSON válido");
    24	        }
    25	        if (json == null || !json.isObject()) {
    26	            throw invalid("O corpo deve ser um objeto JSON");
    27	        }
    28	        LocalDate checkIn = date(json, "checkIn");
    29	        LocalDate checkOut = date(json, "checkOut");
    30	        if (!checkOut.isAfter(checkIn)) {
    31	            throw invalid("A saída deve ser depois da entrada");
    32	        }
    33	        int guests = integer(json, "guests");
    34	        if (guests < 1) {
    35	            throw invalid("É preciso pelo menos um hóspede");
    36	        }
    37	        return new NewReservation(
    38	                integer(json, "roomNumber"),
    39	                text(json, "guestName"),
    40	                text(json, "guestEmail"),
    41	                text(json, "guestCpf"),
    42	                checkIn,
    43	                checkOut,
    44	                guests,
    45	                ratePlan(json));
    46	    }
    47	
    48	    private static String text(JsonNode json, String field) {
    49	        JsonNode node = json.get(field);
    50	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    51	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    52	        }
    53	        return node.asText().trim();
    54	    }
    55	
    56	    private static int integer(JsonNode json, String field) {
    57	        JsonNode node = json.get(field);
    58	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    59	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    60	        }
    61	        return node.asInt();
    62	    }
    63	
    64	    private static LocalDate date(JsonNode json, String field) {
    65	        try {
    66	            return LocalDate.parse(text(json, field));
    67	        } catch (DateTimeParseException e) {
    68	            throw invalid("Data inválida em " + field + " (use 2027-07-10)");
    69	        }
    70	    }
    71	
    72	    private static RatePlan ratePlan(JsonNode json) {
    73	        try {
    74	            return RatePlan.valueOf(text(json, "ratePlan"));
    75	        } catch (IllegalArgumentException e) {
    76	            throw invalid("Plano de tarifa inválido em ratePlan");
    77	        }
    78	    }
    79	
    80	    private static ApiException invalid(String message) {
    81	        return new ApiException(ErrorCode.INVALID_REQUEST, message);
    82	    }
    83	}
