     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	import com.fasterxml.jackson.databind.SerializationFeature;
    10	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    11	import io.javalin.Javalin;
    12	import io.javalin.http.Context;
    13	import java.time.LocalDate;
    14	import java.time.YearMonth;
    15	import java.time.format.DateTimeParseException;
    16	import java.util.Map;
    17	
    18	public class Routes {
    19	    private static final String CSV = "text/csv; charset=utf-8";
    20	
    21	    private final ObjectMapper mapper = new ObjectMapper()
    22	            .registerModule(new JavaTimeModule())
    23	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    24	    private final ReservationService reservations;
    25	    private final ReportService reports;
    26	    private final Outbox outbox;
    27	
    28	    public Routes(ReservationService reservations, ReportService reports, Outbox outbox) {
    29	        this.reservations = reservations;
    30	        this.reports = reports;
    31	        this.outbox = outbox;
    32	    }
    33	
    34	    public void register(Javalin app) {
    35	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    36	
    37	        app.get("/rooms", ctx -> json(ctx, 200, reservations.listRooms()));
    38	        app.post("/reservations", ctx ->
    39	                json(ctx, 201, reservations.create(ReservationRequest.parse(mapper, ctx.body()))));
    40	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservations.get(id(ctx))));
    41	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservations.confirm(id(ctx))));
    42	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservations.cancel(id(ctx))));
    43	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservations.checkIn(id(ctx))));
    44	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, reservations.checkOut(id(ctx))));
    45	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, reservations.document(id(ctx))));
    46	        app.get("/messages", ctx -> json(ctx, 200, outbox.list()));
    47	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(date(ctx.queryParam("date")))));
    48	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(month(ctx.queryParam("month")))));
    49	    }
    50	
    51	    private void json(Context ctx, int status, Object body) throws Exception {
    52	        ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
    53	    }
    54	
    55	    private void csv(Context ctx, String body) {
    56	        ctx.status(200).contentType(CSV).result(body);
    57	    }
    58	
    59	    private void error(Context ctx, ErrorCode code, String message) {
    60	        try {
    61	            json(ctx, code.httpStatus(), Map.of("error", code.name(), "message", message));
    62	        } catch (Exception e) {
    63	            ctx.status(500);
    64	        }
    65	    }
    66	
    67	    private long id(Context ctx) {
    68	        try {
    69	            return Long.parseLong(ctx.pathParam("id"));
    70	        } catch (NumberFormatException e) {
    71	            throw new ApiException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + ctx.pathParam("id") + " não existe");
    72	        }
    73	    }
    74	
    75	    private LocalDate date(String value) {
    76	        try {
    77	            return LocalDate.parse(value);
    78	        } catch (DateTimeParseException | NullPointerException e) {
    79	            throw new ApiException(ErrorCode.INVALID_REQUEST, "Informe date no formato 2027-07-10");
    80	        }
    81	    }
    82	
    83	    private YearMonth month(String value) {
    84	        try {
    85	            if (value == null || !value.matches("\\d{4}-\\d{2}")) {
    86	                throw new DateTimeParseException("formato", String.valueOf(value), 0);
    87	            }
    88	            return YearMonth.parse(value);
    89	        } catch (DateTimeParseException e) {
    90	            throw new ApiException(ErrorCode.INVALID_REQUEST, "Informe month no formato 2027-07");
    91	        }
    92	    }
    93	}

