    37	    public Reservation create(NewReservation request) {
    38	        return database.inTransaction(c -> {
    39	            Room room = rooms.findForUpdate(c, request.roomNumber()).orElseThrow(() ->
    40	                    new ApiException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + request.roomNumber() + " não existe"));
    41	            if (request.guests() > room.capacity()) {
    42	                throw new ApiException(ErrorCode.CAPACITY_EXCEEDED,
    43	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " pessoas");
    44	            }
    45	            if (reservations.existsOverlapping(c, room.number(), request.checkIn(), request.checkOut())) {
    46	                throw new ApiException(ErrorCode.ROOM_UNAVAILABLE,
    47	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    48	            }
    49	            Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    50	            Reservation draft = new Reservation(0, room.number(), request.guestName(), request.guestEmail(),
    51	                    request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan(),
    52	                    quote.nights(), quote.subtotal(), quote.discount(), quote.total(), Status.PENDING,
    53	                    Money.ZERO, null);
    54	            return reservations.insert(c, draft);
