    16	    }
    17	
    18	    static NewReservation parse(ObjectMapper mapper, String body) {
    19	        JsonNode json;
    20	        try {
    21	            json = mapper.readTree(body);
    22	        } catch (JsonProcessingException e) {
    23	            throw invalid("O corpo não é um JSON válido");
    24	        }
    25	        if (json == null || !json.isObject()) {
    26	            throw invalid("O corpo deve ser um objeto JSON");
    27	        }
    28	        LocalDate checkIn = date(json, "checkIn");
    29	        LocalDate checkOut = date(json, "checkOut");
    30	        if (!checkOut.isAfter(checkIn)) {
    31	            throw invalid("A saída deve ser depois da entrada");
    32	        }
    33	        int guests = integer(json, "guests");
    34	        if (guests < 1) {
    35	            throw invalid("É preciso pelo menos um hóspede");
    36	        }
    37	        return new NewReservation(
    38	                integer(json, "roomNumber"),
    39	                text(json, "guestName"),
    40	                text(json, "guestEmail"),
    41	                text(json, "guestCpf"),
    42	                checkIn,
    43	                checkOut,
    44	                guests,
    45	                ratePlan(json));
    46	    }
