    18	public class Routes {
    19	    private static final String CSV = "text/csv; charset=utf-8";
    20	
    21	    private final ObjectMapper mapper = new ObjectMapper()
    22	            .registerModule(new JavaTimeModule())
    23	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    24	    private final ReservationService reservations;
    25	    private final ReportService reports;
