    28	    public Routes(ReservationService reservations, ReportService reports, Outbox outbox) {
    29	        this.reservations = reservations;
    30	        this.reports = reports;
    31	        this.outbox = outbox;
    32	    }
    33	
    34	    public void register(Javalin app) {
    35	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    36	
    37	        app.get("/rooms", ctx -> json(ctx, 200, reservations.listRooms()));
    38	        app.post("/reservations", ctx ->
    39	                json(ctx, 201, reservations.create(ReservationRequest.parse(mapper, ctx.body()))));
    40	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservations.get(id(ctx))));
    41	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservations.confirm(id(ctx))));
    42	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservations.cancel(id(ctx))));
    43	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservations.checkIn(id(ctx))));
    44	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, reservations.checkOut(id(ctx))));
    45	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, reservations.document(id(ctx))));
    46	        app.get("/messages", ctx -> json(ctx, 200, outbox.list()));
    47	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(date(ctx.queryParam("date")))));
    48	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(month(ctx.queryParam("month")))));
    49	    }
