     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {
    11	    }
    12	
    13	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    14	    public static boolean highSeason(LocalDate night) {
    15	        Month month = night.getMonth();
    16	        return month == Month.JULY
    17	                || month == Month.JANUARY
    18	                || month == Month.FEBRUARY
    19	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    20	    }
    21	
    22	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    23	        BigDecimal rate = room.nightlyRate();
    24	        return Money.round(highSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    25	    }
    26	
    27	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    28	        BigDecimal subtotal = Money.ZERO;
    29	        int nights = 0;
    30	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    31	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    32	            nights++;
    33	        }
    34	        BigDecimal discount = plan.discountOn(subtotal);
    35	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    36	    }
    37	}
