    21	                guest_email  VARCHAR(200) NOT NULL,
    22	                guest_cpf    VARCHAR(30) NOT NULL,
    23	                check_in     DATE NOT NULL,
    24	                check_out    DATE NOT NULL,
    25	                guests       INTEGER NOT NULL,
    26	                rate_plan    VARCHAR(20) NOT NULL,
    27	                nights       INTEGER NOT NULL,
    28	                subtotal     NUMERIC(12,2) NOT NULL,
    29	                discount     NUMERIC(12,2) NOT NULL,
    30	                total        NUMERIC(12,2) NOT NULL,
    31	                status       VARCHAR(20) NOT NULL,
    32	                amount_paid  NUMERIC(12,2) NOT NULL,
    33	                refund       NUMERIC(12,2)
    34	            );
    35	            CREATE TABLE IF NOT EXISTS messages (
    36	                id        BIGSERIAL PRIMARY KEY,
    37	                channel   VARCHAR(20) NOT NULL,
    38	                recipient VARCHAR(300) NOT NULL,
    39	                subject   VARCHAR(500) NOT NULL,
    40	                body      TEXT NOT NULL,
    41	                status    VARCHAR(20) NOT NULL
    42	            );
    43	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    44	                (101, 'STANDARD', 2, 249.90),
    45	                (102, 'STANDARD', 2, 249.90),
    46	                (201, 'DELUXE', 3, 389.90),
    47	                (202, 'DELUXE', 3, 389.90),
    48	                (301, 'SUITE', 4, 579.90)
    49	            ON CONFLICT (number) DO NOTHING;
    50	            """;
    51	
    52	    public interface Work<T> {
    53	        T run(Connection connection) throws SQLException;
    54	    }
    55	
    56	    private final HikariDataSource dataSource;
    57	
    58	    public Database(String url, String user, String password) {
    59	        HikariConfig config = new HikariConfig();
    60	        config.setJdbcUrl(url);
    61	        config.setUsername(user);
    62	        config.setPassword(password);
    63	        config.setMaximumPoolSize(10);
    64	        config.setInitializationFailTimeout(60_000);
    65	        this.dataSource = new HikariDataSource(config);
    66	    }
    67	
    68	    /** Cria o que o sistema precisa; um lock evita que duas instâncias subindo juntas se atropelem. */
    69	    public void migrate() {
    70	        inTransaction(c -> {
    71	            try (Statement s = c.createStatement()) {
    72	                s.execute("SELECT pg_advisory_xact_lock(727001)");
    73	                s.execute(SCHEMA);
    74	            }
    75	            return null;
    76	        });
    77	    }
    78	
    79	    public <T> T inTransaction(Work<T> work) {
    80	        try (Connection c = dataSource.getConnection()) {
    81	            c.setAutoCommit(false);
    82	            try {
    83	                T result = work.run(c);
    84	                c.commit();
    85	                return result;
    86	            } catch (SQLException | RuntimeException e) {
    87	                c.rollback();
    88	                throw e;
    89	            }
    90	        } catch (SQLException e) {
    91	            throw new IllegalStateException("Erro no banco de dados", e);
    92	        }
    93	    }
    94	
    95	    @Override
    96	    public void close() {
    97	        dataSource.close();
    98	    }
    99	}
