    16	        RatePlan ratePlan,
    17	        int nights,
    18	        BigDecimal subtotal,
    19	        BigDecimal discount,
    20	        BigDecimal total,
    21	        Status status,
    22	        BigDecimal amountPaid,
    23	        BigDecimal refund) {
    24	
    25	    public Reservation confirm() {
    26	        requireStatus("confirmada", Status.PENDING);
    27	        return with(Status.CONFIRMED, total, refund);
    28	    }
    29	
    30	    public Reservation startStay() {
    31	        requireStatus("feito o check-in", Status.CONFIRMED);
    32	        return with(Status.CHECKED_IN, amountPaid, refund);
    33	    }
    34	
    35	    public Reservation endStay() {
    36	        requireStatus("feito o check-out", Status.CHECKED_IN);
    37	        return with(Status.CHECKED_OUT, amountPaid, refund);
    38	    }
    39	
    40	    public Reservation cancel() {
    41	        requireStatus("cancelada", Status.PENDING, Status.CONFIRMED);
    42	        return with(Status.CANCELLED, amountPaid, ratePlan.refundFor(amountPaid));
    43	    }
    44	
    45	    /** O que ficou com a pousada: pago menos devolvido. */
    46	    public BigDecimal retained() {
